/**
 * Divination suite — four oracular systems, all drawn from the same entropy
 * stream as the Quantum Seed (drand beacon, CSPRNG fallback):
 *
 *   - Geomancy: full 16-figure shield chart generated by the classical
 *     algorithm (Mothers → Daughters → Nieces → Witnesses → Judge), plus
 *     the Requerant and Sentence derived by figure addition.
 *   - Runes: 24-elder Futhark draw (single / three Norn spread).
 *   - Tarot: 78-card Rider–Waite–Smith deck, upright/reversed,
 *     single card / three-card past–present–future.
 *   - I Ching: six-line coin-method hexagram with King Wen number/name,
 *     changing lines, and the derived second hexagram.
 *
 * Every draw consumes fresh entropy via drawEntropy() so the beacon
 * provenance carries through the whole suite.
 */

import { drawEntropy } from './entropy';

// =====================================================================
// Entropy plumbing
// =====================================================================

/**
 * A bit-stream over freshly drawn entropy. Hex chars → 4 bits each;
 * `bits(n)` returns the next n bits as an integer. The timestamp keeps
 * two draws in the same millisecond from returning identical streams.
 */
async function entropyStream(): Promise<(n: number) => number> {
    const { hex } = await drawEntropy();
    let pos = 0;
    let extra = Math.floor(Math.random() * 0xffffffff);
    return (n: number): number => {
        let v = 0;
        for (let i = 0; i < n; i++) {
            if (pos >= hex.length) {
                extra = (extra * 1664525 + 1013904223) >>> 0;
                v = (v << 1) | (extra & 1);
                extra = (extra >>> 1) | (extra << 31);
                continue;
            }
            const nib = parseInt(hex[pos], 16);
            const bit = (nib >> (3 - (pos % 4))) & 1;
            v = (v << 1) | bit;
            pos++;
        }
        return v;
    };
}

