export const GEO_FIGURES: GeoFigure[] = GEO_PATTERNS.map((p, i) => ({
    ...p,
    ...GEO_META[i],
}));

/** Classical addition: per line, same → 0 (two dots), different → 1 (one dot). XOR. */
export function geoAdd(a: GeoFigure, b: GeoFigure): GeoFigure {
    const lines: [number, number, number, number] = [
        a.lines[0] ^ b.lines[0],
        a.lines[1] ^ b.lines[1],
        a.lines[2] ^ b.lines[2],
        a.lines[3] ^ b.lines[3],
    ];
    return GEO_FIGURES.find(f => f.lines.every((l, i) => l === lines[i]))!;
}

export interface GeoReading {
    mothers: GeoFigure[];
    daughters: GeoFigure[];
    nieces: GeoFigure[];
    witnesses: [GeoFigure, GeoFigure];
    judge: GeoFigure;
    requerant: GeoFigure;
    sentence: GeoFigure;
}

/**
 * Full shield chart. Mothers come from the entropy stream (4 figures ×
 * 4 lines); everything else is derived by the classical algorithm:
 * daughters rotate the mother lines; nieces 1–4 add M1+M2, M3+M4,
 * D1+D2, D3+D4; witnesses add niece pairs; the Judge adds the witnesses
 * (its point count is always even by construction). The Requerant adds
 * the Judge to the First Witness; the Sentence adds the Judge to the
 * First Mother.
 */
export async function castGeomancy(): Promise<GeoReading> {
    const bits = await entropyStream();

    const mothers: GeoFigure[] = [];
    for (let m = 0; m < 4; m++) {
        const lines: [number, number, number, number] = [
            bits(1), bits(1), bits(1), bits(1),
        ];
        mothers.push(GEO_FIGURES.find(f => f.lines.every((l, i) => l === lines[i]))!);
    }

    // Daughters: daughter i takes line i from each mother, top→bottom.
    const daughters: GeoFigure[] = [0, 1, 2, 3].map(i => {
        const lines: [number, number, number, number] = [
            mothers[0].lines[i], mothers[1].lines[i], mothers[2].lines[i], mothers[3].lines[i],
        ];
        return GEO_FIGURES.find(f => f.lines.every((l, j) => l === lines[j]))!;
    });

    const n1 = geoAdd(mothers[0], mothers[1]);
    const n2 = geoAdd(mothers[2], mothers[3]);
    const n3 = geoAdd(daughters[0], daughters[1]);
    const n4 = geoAdd(daughters[2], daughters[3]);
    const w1 = geoAdd(n1, n2);
    const w2 = geoAdd(n3, n4);
    const judge = geoAdd(w1, w2);
    const requerant = geoAdd(judge, w1);
    const sentence = geoAdd(judge, mothers[0]);

    return { mothers, daughters, nieces: [n1, n2, n3, n4], witnesses: [w1, w2], judge, requerant, sentence };
}

