export interface RuneDraw {
    spread: 'single' | 'norns';
    stones: Array<{ rune: Rune; reversed: boolean; position: string }>;
}

export async function castRunes(spread: 'single' | 'norns'): Promise<RuneDraw> {
    const bits = await entropyStream();
    const positions = spread === 'single' ? ['The Matter'] : ['Past — Urd', 'Present — Verdandi', 'Future — Skuld'];
    const used = new Set<number>();
    const stones = positions.map(position => {
        let idx = bits(5);
        while (idx >= 24 || used.has(idx)) idx = bits(5);
        used.add(idx);
        return { rune: ELDER_FUTHARK[idx], reversed: bits(1) === 1, position };
    });
    return { spread, stones };
}

