export const TAROT_DECK: TarotCard[] = [
    ...MAJORS.map(([name, keywords], i) => ({ name, arcana: 'major' as const, number: i, keywords })),
    ...SUITS.flatMap(s =>
        s.rankKeywords.map((kw, i) => ({
            name: `${i === 0 ? 'Ace' : i < 10 ? ['Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten'][i - 1] : ['Page', 'Knight', 'Queen', 'King'][i - 10]} of ${s.suit}`,
            arcana: 'minor' as const,
            suit: s.suit,
            number: i,
            keywords: `${kw} (${s.elem})`,
        }))
    ),
];

export interface TarotDraw {
    spread: 'single' | 'three';
    cards: Array<{ card: TarotCard; reversed: boolean; position: string }>;
}

export async function castTarot(spread: 'single' | 'three'): Promise<TarotDraw> {
    const bits = await entropyStream();
    const positions = spread === 'single'
        ? ['The Reading']
        : ['Past', 'Present', 'Future'];
    const used = new Set<number>();
    const cards = positions.map(position => {
        let idx = bits(7);
        while (idx >= 78 || used.has(idx)) idx = bits(7);
        used.add(idx);
        return { card: TAROT_DECK[idx], reversed: bits(1) === 1, position };
    });
    return { spread, cards };
}

// =====================================================================
// I Ching — coin method, King Wen numbering
// =====================================================================

export interface HexagramInfo {
    number: number;
    name: string;
    chinese: string;
    /** Unicode hexagram character U+4DC0 + (number-1). */
    glyph: string;
    /** Lines bottom→top: 1 yang, 0 yin. */
    lines: number[];
}

/**
 * King Wen numbers indexed [lower trigram binary][upper trigram binary].
 * Trigram binary value: bottom line ×1, middle ×2, top ×4, yang = 1 —
 * so index 0 = ☷ Kun(Earth), 1 = ☳ Chen(Thunder), 2 = ☵ Kan(Water),
 * 3 = ☱ Tui(Lake), 4 = ☶ Ken(Mountain), 5 = ☲ Li(Fire), 6 = ☴ Sun(Wind),
 * 7 = ☰ Chien(Heaven). Every cell cross-checked against the standard
 * 8×8 matrix and the classical lower/upper assignments of the 64.
 */
const KING_WEN: number[][] = [
    [ 2, 16,  8, 45, 23, 35, 20, 12], // lower Kun   (Earth)
    [24, 51,  3, 17, 27, 21, 42, 25], // lower Chen  (Thunder)
    [ 7, 40, 29, 47,  4, 64, 59,  6], // lower Kan   (Water)
    [19, 54, 60, 58, 41, 38, 61, 10], // lower Tui   (Lake)
    [15, 62, 39, 31, 52, 56, 53, 33], // lower Ken   (Mountain)
    [36, 55, 63, 49, 22, 30, 37, 13], // lower Li    (Fire)
    [46, 32, 48, 28, 57, 50, 18, 44], // lower Sun   (Wind)
    [11, 34,  5, 43, 26, 14,  9,  1], // lower Chien (Heaven)
];
const HEXAGRAM_NAMES: Record<number, [string, string]> = {
    1: ['Qian', 'The Creative'], 2: ['Kun', 'The Receptive'], 3: ['Zhun', 'Difficulty at the Beginning'],
    4: ['Meng', 'Youthful Folly'], 5: ['Xu', 'Waiting'], 6: ['Song', 'Conflict'],
    7: ['Shi', 'The Army'], 8: ['Bi', 'Holding Together'], 9: ['Xiao Chu', 'Small Accumulating'],
    10: ['Lü', 'Treading'], 11: ['Tai', 'Peace'], 12: ['Pi', 'Standstill'],
    13: ['Tong Ren', 'Fellowship'], 14: ['Da You', 'Great Possession'], 15: ['Qian', 'Modesty'],
    16: ['Yu', 'Enthusiasm'], 17: ['Sui', 'Following'], 18: ['Gu', 'Work on the Decayed'],
    19: ['Lin', 'Approach'], 20: ['Guan', 'Contemplation'], 21: ['Shi He', 'Biting Through'],
    22: ['Bi', 'Grace'], 23: ['Bo', 'Splitting Apart'], 24: ['Fu', 'Return'],
    25: ['Wu Wang', 'Innocence'], 26: ['Da Xu', 'Great Accumulating'], 27: ['Yi', 'Nourishment'],
    28: ['Da Guo', 'Great Exceeding'], 29: ['Xi Kan', 'The Abyss'], 30: ['Li', 'Radiance'],
    31: ['Xian', 'Influence'], 32: ['Heng', 'Duration'], 33: ['Dun', 'Retreat'],
    34: ['Da Zhuang', 'Great Power'], 35: ['Jin', 'Progress'], 36: ['Ming Yi', 'Darkening of the Light'],
    37: ['Jia Ren', 'The Family'], 38: ['Kui', 'Opposition'], 39: ['Jian', 'Obstruction'],
    40: ['Xie', 'Deliverance'], 41: ['Sun', 'Decrease'], 42: ['Yi', 'Increase'],
    43: ['Guai', 'Breakthrough'], 44: ['Gou', 'Coming to Meet'], 45: ['Cui', 'Gathering Together'],
    46: ['Sheng', 'Pushing Upward'], 47: ['Kun', 'Oppression'], 48: ['Jing', 'The Well'],
    49: ['Ge', 'Revolution'], 50: ['Ding', 'The Cauldron'], 51: ['Zhen', 'The Arousing'],
    52: ['Gen', 'Keeping Still'], 53: ['Jian', 'Development'], 54: ['Gui Mei', 'The Marrying Maiden'],
    55: ['Feng', 'Abundance'], 56: ['Lü', 'The Wanderer'], 57: ['Xun', 'The Gentle'],
    58: ['Dui', 'The Joyous'], 59: ['Huan', 'Dispersion'], 60: ['Jie', 'Limitation'],
    61: ['Zhong Fu', 'Inner Truth'], 62: ['Xiao Guo', 'Small Exceeding'], 63: ['Ji Ji', 'After Completion'],
    64: ['Wei Ji', 'Before Completion'],
};

function hexagramInfo(lines: number[]): HexagramInfo {
    // lines bottom→top; trigram value: bottom ×1, middle ×2, top ×4, yang=1.
    // Index 0..7 = Kun, Chen, Kan, Tui, Ken, Li, Sun, Chien.
    const lower = lines[0] + 2 * lines[1] + 4 * lines[2];
    const upper = lines[3] + 2 * lines[4] + 4 * lines[5];
    const num = KING_WEN[lower][upper];
    const [chinese, name] = HEXAGRAM_NAMES[num];
    return { number: num, name, chinese, glyph: String.fromCodePoint(0x4dc0 + num - 1), lines: [...lines] };
}

export interface IchingReading {
    /** First hexagram (the situation). */
    primary: HexagramInfo;
    /** Second hexagram if any lines change, else null. */
    secondary: HexagramInfo | null;
    /** Indexes (0 = bottom) of the changing lines. */
    changing: number[];
    /** Coin values bottom→top: 6 old-yin, 7 yang, 8 yin, 9 old-yang. */
    tosses: number[];
}

/** Coin method: three coins per line; 6 = old yin (changing), 9 = old yang (changing). */
export async function castIChing(): Promise<IchingReading> {
    const bits = await entropyStream();
    const lines: number[] = [];
    const tosses: number[] = [];
    const changing: number[] = [];

    for (let i = 0; i < 6; i++) {
        const heads = bits(1) + bits(1) + bits(1); // 0..3 heads
        const value = 6 + heads; // 6,7,8,9
        tosses.push(value);
        const yang = value === 7 || value === 9;
        lines.push(yang ? 1 : 0);
        if (value === 6 || value === 9) changing.push(i);
    }

    const primary = hexagramInfo(lines);
    let secondary: HexagramInfo | null = null;
    if (changing.length > 0) {
        const flipped = lines.map((l, i) => (changing.includes(i) ? 1 - l : l));
        secondary = hexagramInfo(flipped);
    }
    return { primary, secondary, changing, tosses };
}

/** Small helper for the UI: trigram name for a hexagram's lower/upper third. */
export function trigramName(lines: number[], upper: boolean): string {
    const l = upper ? lines.slice(3) : lines.slice(0, 3);
    const v = l[0] + 2 * l[1] + 4 * l[2];
    return ['Kun', 'Chen', 'Kan', 'Tui', 'Ken', 'Li', 'Sun', 'Chien'][v];
}

export const ICHING_TRIGRAMS: Record<string, { glyph: string; nature: string }> = {
    Chien: { glyph: '☰', nature: 'Heaven' }, Tui: { glyph: '☱', nature: 'Lake' },
    Li: { glyph: '☲', nature: 'Fire' }, Chen: { glyph: '☳', nature: 'Thunder' },
    Sun: { glyph: '☴', nature: 'Wind' }, Kan: { glyph: '☵', nature: 'Water' },
    Ken: { glyph: '☶', nature: 'Mountain' }, Kun: { glyph: '☷', nature: 'Earth' },
};
